-- Purge des lignes precedemment chargees pour cette date/categorie (donnees erronees a base de soldes cumules)
DELETE FROM RPT_RENTABILITE WHERE CATEGORIE = 'Consolidé' AND DATE_ARRETE = TO_DATE('2026-06-30','YYYY-MM-DD');

